#pragma once

#include "base.hpp"

namespace epi::presets {

/**
 * F0 Catenoid Minimal Arc — showcase for GPU inner ID 20.
 *
 *      f(z) = z · cosh(z)
 *
 * MATHEMATICS: CATENOID — MINIMAL SURFACE OF REVOLUTION (Euler 1744)
 *
 * The catenoid is the unique minimal surface of revolution and the first
 * non-trivial minimal surface discovered in history (Euler 1744, proven
 * by Meusnier 1776).  It is generated by rotating a CATENARY
 * y = a·cosh(x/a) about the x-axis.  The catenary itself is the shape of
 * a hanging chain under uniform gravity — the curve minimizing potential
 * energy subject to fixed endpoints and fixed arc length.
 *
 * MEAN CURVATURE = 0 everywhere (the defining property of minimal surfaces):
 *   H = (k₁ + k₂)/2 = 0 ↔ k₁ = −k₂
 * The principal curvatures are equal in magnitude but opposite in sign —
 * every point is a saddle, balancing outward curvature in one direction with
 * equal inward curvature perpendicular.  This is why soap films form
 * catenoids: surface tension minimizes area, which requires H ≡ 0.
 *
 * COMPLEX REPRESENTATION:
 *
 *   z · cosh(z) encodes the catenoid parametrically.
 *   In the Weierstrass-Enneper representation, all minimal surfaces are
 *   encoded by a pair (f, g) of meromorphic functions.  For the catenoid:
 *     f(w) = 1,  g(w) = w⁻¹
 *   giving parametrization X(w) = ½·Re∫[w⁻² + 1, i(w⁻²−1), 2w⁻¹] dw.
 *   The product z·cosh(z) captures the GROWTH-WITH-SHAPE character: z
 *   provides position-dependent weight and cosh provides the catenary's
 *   saddle profile.  Under iteration, this creates arch sequences that
 *   resemble the vertical cross-sections of a catenoid tower.
 *
 * THE SISTER SURFACE — HELICOID (Meusnier 1776):
 *   The catenoid and helicoid are ISOMETRICALLY EQUIVALENT: one can be
 *   continuously bent into the other without stretching.  The family
 *   X_t = cos(t)·X_cat + sin(t)·X_hel smoothly interpolates between them,
 *   and every X_t is itself a minimal surface.  This is the most famous
 *   isometric deformation of a minimal surface.
 *
 * AFFINE ANGLES — CATENARY DIFFERENTIAL GEOMETRY:
 *
 *   PRE-ROTATION = arccos(tanh(1)) ≈ 40.25°
 *     tanh(1) = (e²−1)/(e²+1) ≈ 0.7616
 *     sech(1) = 2/(e+e⁻¹)    ≈ 0.6481
 *     This is the inclination angle of the catenoid's unit normal at the
 *     point s = 1 along the arc from the neck.  At the neck (s=0) the
 *     normal is horizontal; it rotates to arccos(tanh(s)) as s increases.
 *     At s=1 the saddle opens by exactly arccos(tanh(1)) from vertical.
 *     Equivalently: this is the angle at which sinh(1)/cosh(1) = tanh(1)
 *     describes the catenary's tangent slope.
 *
 *   POST-ROTATION = −arctan(2) ≈ −63.43°
 *     cos(arctan(2)) = 1/√5,  sin(arctan(2)) = 2/√5
 *     arctan(2) appears in the SCHWARZ-CHRISTOFFEL conformal map between
 *     the catenoid and the flat cylinder: integrating the map
 *     dz/dw = √(w²+1)/(w²) produces the angle arctan(2) as the argument
 *     of the residue at the branch points ±i.  It also appears in the
 *     PENROSE RHOMBUS angles (the acute angle of the fat rhombus is
 *     arctan(2) ≈ 63.43°), connecting minimal surfaces to quasicrystal geometry.
 *
 *   CONTRACTION: PRE=0.91, POST=0.80 — z·cosh grows as |z|·e^|Re(z)|/2
 *     for large |z|; aggressive post-contraction is mandatory.
 *     Combined shrinkage per depth layer: 0.91 × 0.80 = 0.728.
 *
 * COLOR MODE 1 — SPIRAL:
 *
 *   h = hue_rotation·t + spiral_a·angle(z) + spiral_r·log|z|
 *
 *   The log|z| term reveals the EXPONENTIAL GROWTH LAYERS of cosh —
 *   each depth ring corresponds to one "generation" of the catenary arch.
 *   The angle term shows the SADDLE STRUCTURE: the two-fold symmetry of
 *   cosh (even function) creates two mirrored arch families, and the
 *   spiral color distinguishes the approach direction to each saddle.
 *
 * Pipeline: transform → reduce(torus) → sample → color(mode1) → seed → blend
 */
inline Pattern f0_catenoid_minimal_arc() {
  // Catenary neck-normal angle: arccos(tanh(1)) ≈ 40.25°
  // tanh(1) = (e²-1)/(e²+1), sech(1) = 2/(e+e⁻¹), tanh² + sech² = 1 ✓
  constexpr float CTANH1 =  0.7616f;  // tanh(1) ≈ cos(catenoid neck angle)
  constexpr float CSECH1 =  0.6481f;  // sech(1) ≈ sin(catenoid neck angle)
  // Schwarz-Christoffel / Penrose rhombus angle: arctan(2) ≈ 63.43°
  // cos(arctan(2)) = 1/√5, sin(arctan(2)) = 2/√5
  constexpr float C1S5  =  0.4472f;   // 1/√5 = cos(arctan(2))
  constexpr float C2S5N = -0.8944f;   // -2/√5 = -sin(arctan(2))

  constexpr float PRE  = 0.91f;  // moderate: tame z·cosh growth
  constexpr float POST = 0.80f;  // strong: keep within catenoid basin

  Pattern p;
  p.name = "f0_catenoid_minimal_arc";
  // Named-enum path: InnerFunction::F0 ↔ GPU id 20 (z·cosh(z))
  p.inner = InnerFunction::F0;
  p.extended_inner_id = -1;
  p.reduction = ReductionType::Torus;

  // Pre-rotate by catenary neck angle: reveals the minimal surface symmetry
  p.zn.zn[0] = {CTANH1 * PRE,  CSECH1 * PRE};
  p.zn.zn[1] = {0.0f,          0.003f};    // thermal perturbation
  // Post-rotate by -arctan(2): Schwarz-Christoffel conformal mapping angle
  p.zn.zn[2] = {C1S5   * POST, C2S5N * POST};
  p.zn.zn[3] = {0.0f,          0.0f};

  // ── Color: MODE 1 (Spiral) — depth rings reveal cosh growth layers ──
  p.color.hue_rotation      = 0.005f;   // slow: spiral geometry dominates
  p.color.sat_scale         = 1.10f;    // moderate: clean minimal surface aesthetic
  p.color.fade              = 0.989f;   // deep: ~91 frame arch memory
  p.color.color_mode        = as_int(ColorMode::Spiral);        // Spiral: h = a·angle + r·log|z|
  p.color.spiral_angle_coeff  = 1.35f;  // moderate: two-branch saddle structure
  p.color.spiral_radius_coeff = 0.65f;  // strong log(r): reveals cosh depth layers
  // Mode 1 does not use breathing or hue velocity
  p.color.chroma_breath_amp   = 0.0f;
  p.color.chroma_breath_freq  = 0.0f;
  p.color.chroma_breath_phase = 0.0f;
  p.color.hue_velocity_base   = 0.0f;
  p.color.hue_velocity_breath = 0.0f;
  p.color.hue_velocity_drift  = 0.0f;
  // Luminance: saddle geometry creates natural depth cues
  p.color.luma_shape_depth    = 0.20f;
  p.color.luma_shape_center   = 2.0f;

  // ── Seed: subtle — catenoid self-generates from feedback arch cascade ──
  p.seed.border_width = 0.010f;
  p.seed.hue          = 0.55f;    // blue-teal: minimal surface ocean geometry
  p.seed.hue_speed    = 0.015f;
  p.seed.alpha        = 0.85f;

  p.speed = 0.39f;
  p.zn.zn0_animate = true;
  p.zn.zn0_anim_speed = 0.127f;
  p.zn.zn0_anim_amp = 0.045f;
  p.zn.zn1_animate = true;
  p.zn.zn1_anim_speed = 0.198f;
  p.zn.zn1_anim_amp = 0.037f;
  p.zn.zn1_anim_k = 6.0f;
  p.seed.pulse_freq = 0.134f;
  p.seed.pulse_amp = 0.15f;
  p.motion
      .add("radial_pitch_wave",
           control::ModLane{.wave = control::Waveform::Sine,
                            .frequency_hz = 0.075f,
                            .amplitude = 0.182f,
                            .offset = 0.650f},
           control::ModTarget::SpiralRadiusCoeff)
      .add("chroma_diaphragm",
           control::ModLane{.wave = control::Waveform::Sine,
                            .frequency_hz = 0.098f,
                            .amplitude = 0.050f,
                            .offset = 0.000f,
                            .phase = 0.25f},
           control::ModTarget::ChromaBreathAmp)
      .add("seed_spectrum_tide",
           control::ModLane{.wave = control::Waveform::Triangle,
                            .frequency_hz = 0.078f,
                            .amplitude = 0.030f,
                            .offset = 0.015f},
           control::ModTarget::SeedHueSpeed);


  return p;
}

} // namespace epi::presets
